package dao;
import model.RolePermission;import util.DBContext;import java.sql.*;import java.util.*;
public class RolePermissionDAO {
 public List<RolePermission> getAllPermissions(){List<RolePermission>list=new ArrayList<>();try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("SELECT module_code,MAX(CASE WHEN role_code='ADMIN' THEN CONVERT(int,can_access) ELSE 0 END) a,MAX(CASE WHEN role_code='STAFF' THEN CONVERT(int,can_access) ELSE 0 END) s,MAX(CASE WHEN role_code='VIEWER' THEN CONVERT(int,can_access) ELSE 0 END) v FROM RolePermission GROUP BY module_code ORDER BY module_code");ResultSet r=p.executeQuery()){int i=0;while(r.next()){RolePermission x=new RolePermission();x.setPermId(++i);x.setModuleKey(r.getString(1));x.setModuleName(r.getString(1).replace('_',' '));x.setOperationalScope("Server enforced access");x.setAdminAllowed(r.getBoolean(2));x.setStaffAllowed(r.getBoolean(3));x.setViewerAllowed(r.getBoolean(4));list.add(x);}}catch(Exception e){System.err.println("Cannot load role permissions: "+e.getMessage());}return list;}
 public boolean updatePermission(String key,String role,boolean allowed){if("ADMIN".equals(role))return false;if(!"STAFF".equals(role)&&!"VIEWER".equals(role))return false;try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("UPDATE RolePermission SET can_access=? WHERE module_code=? AND role_code=?")){p.setBoolean(1,allowed);p.setString(2,key);p.setString(3,role);return p.executeUpdate()==1;}catch(Exception e){return false;}}
 public boolean allowed(String key,String role){if("ADMIN".equals(role))return true;try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("SELECT can_access FROM RolePermission WHERE role_code=? AND module_code=?")){p.setString(1,role);p.setString(2,key);try(ResultSet r=p.executeQuery()){return r.next()&&r.getBoolean(1);}}catch(Exception e){return false;}}
}
